import { Pipe, PipeTransform } from '@angular/core';
import { StatusType } from '../components/data-display/nx-status-chip/nx-status-chip';

const STATUS_LABELS: Record<StatusType, string> = {
  draft: 'Draft',
  pending: 'Pending',
  approved: 'Approved',
  complete: 'Complete',
  received: 'Received',
  rejected: 'Rejected',
  active: 'Active',
  inactive: 'Inactive',
};

@Pipe({ name: 'statusLabel', standalone: false })
export class StatusLabelPipe implements PipeTransform {
  transform(value: StatusType | string): string {
    return STATUS_LABELS[value as StatusType] ?? value;
  }
}

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'truncate', standalone: false })
export class TruncatePipe implements PipeTransform {
  transform(value: string, limit = 50, trail = '…'): string {
    if (!value) return '';
    return value.length > limit ? value.substring(0, limit) + trail : value;
  }
}

