import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { Product, Category, StockAdjustment } from './models';
import { MOCK_PRODUCTS, MOCK_CATEGORIES, MOCK_ADJUSTMENTS } from './mock-data';

@Injectable({ providedIn: 'root' })
export class InventoryService {
  private products = [...MOCK_PRODUCTS];
  private categories = [...MOCK_CATEGORIES];
  private nextCategoryId = this.categories.length + 1;

  getProducts(): Observable<Product[]> { return of(this.products); }
  getProduct(id: number): Observable<Product | undefined> {
    return of(this.products.find(p => p.id === id));
  }
  getCategories(): Observable<Category[]> { return of(this.categories); }
  getAdjustments(): Observable<StockAdjustment[]> { return of(MOCK_ADJUSTMENTS); }
  getLowStockProducts(): Observable<Product[]> {
    return of(this.products.filter(p => p.stockQty <= p.reorderLevel));
  }

  addCategory(data: Partial<Category>): Observable<Category> {
    const category: Category = {
      id: this.nextCategoryId++,
      name: data.name || '',
      description: data.description || '',
      productCount: 0,
    };
    this.categories.push(category);
    return of(category);
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface AppNotification {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
  timestamp: string;
  read: boolean;
}

@Injectable({ providedIn: 'root' })
export class NotificationService {
  private notifications: AppNotification[] = [
    { id: 1, message: '5 products are below reorder level', type: 'warning', timestamp: '2026-06-03T09:00:00', read: false },
    { id: 2, message: 'Purchase Order PO-2024-089 approved', type: 'info', timestamp: '2026-06-03T08:30:00', read: false },
    { id: 3, message: 'Supplier SUPP-041 contract expiring in 7 days', type: 'warning', timestamp: '2026-06-02T16:00:00', read: false },
  ];

  notifications$ = new BehaviorSubject<AppNotification[]>(this.notifications);

  get unreadCount(): number {
    return this.notifications.filter(n => !n.read).length;
  }

  markAllRead(): void {
    this.notifications = this.notifications.map(n => ({ ...n, read: true }));
    this.notifications$.next(this.notifications);
  }
}

import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { PurchaseOrder, PurchaseOrderLine, Requisition } from './models';
import { MOCK_PURCHASE_ORDERS, MOCK_REQUISITIONS } from './mock-data';

@Injectable({ providedIn: 'root' })
export class PurchasingService {
  private orders = [...MOCK_PURCHASE_ORDERS];
  private requisitions = [...MOCK_REQUISITIONS];

  getPurchaseOrders(): Observable<PurchaseOrder[]> { return of(this.orders); }
  getPurchaseOrder(id: number): Observable<PurchaseOrder | undefined> {
    return of(this.orders.find(p => p.id === id));
  }
  getRequisitions(): Observable<Requisition[]> { return of(this.requisitions); }
  getPendingApprovals(): Observable<PurchaseOrder[]> {
    return of(this.orders.filter(p => p.status === 'pending'));
  }

  addPurchaseOrder(data: Partial<PurchaseOrder>): Observable<PurchaseOrder> {
    const nextId = Math.max(...this.orders.map(o => o.id), 0) + 1;
    const po: PurchaseOrder = {
      id: nextId,
      poNumber: `PO-${new Date().getFullYear()}-${String(nextId).padStart(3, '0')}`,
      supplierId: 0,
      supplierName: '',
      status: 'draft',
      orderDate: new Date().toISOString().split('T')[0],
      expectedDate: '',
      totalAmount: 0,
      lines: [] as PurchaseOrderLine[],
      notes: '',
      ...data,
    };
    this.orders.push(po);
    return of(po);
  }

  addRequisition(data: Partial<Requisition>): Observable<Requisition> {
    const nextId = Math.max(...this.requisitions.map(r => r.id), 0) + 1;
    const req: Requisition = {
      id: nextId,
      reqNumber: `REQ-${new Date().getFullYear()}-${String(nextId).padStart(3, '0')}`,
      requestedBy: '',
      department: '',
      status: 'draft',
      requestDate: new Date().toISOString().split('T')[0],
      requiredDate: '',
      description: '',
      estimatedCost: 0,
      ...data,
    };
    this.requisitions.push(req);
    return of(req);
  }
}

import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { Supplier, SupplierContact } from './models';
import { MOCK_SUPPLIERS } from './mock-data';

@Injectable({ providedIn: 'root' })
export class SuppliersService {
  private suppliers = [...MOCK_SUPPLIERS];

